/* Sonidos de batería por defecto de SampledHead App (mid-box y Generador), del usuario: DFBv3 kick/snare/hat/open hat.
   WAV 16 bit 44,1 kHz, recortados al silencio final (−60 dB). shDefaultDrums() → Promise<[AudioBuffer×4]> (bombo, caja, hat cerrado, hat abierto). */
(function () {
  var D = {"k": {"n": "DFB Bombo", "w": ""}, "s": {"n": "DFB Caja", "w": ""}, "h": {"n": "DFB Hat cerrado", "w": ""}, "o": {"n": "DFB Hat abierto", "w": ""}};
  var cache = null;
  window.SH_DRUM_NAMES = ['k', 's', 'h', 'o'].map(function (k) { return D[k].n; });
  window.shDefaultDrums = function (ac) {
    if (cache) return cache;
    cache = Promise.all(['k', 's', 'h', 'o'].map(function (k) {
      var b = atob(D[k].w), u = new Uint8Array(b.length); for (var i = 0; i < b.length; i++) u[i] = b.charCodeAt(i);
      return ac.decodeAudioData(u.buffer).catch(function () { return null; });
    }));
    return cache;
  };
})();
